<script setup lang="ts">
import { onLoad } from "@dcloudio/uni-app"; import { ref } from "vue"; import { trackEvent } from "@/analytics"; import { projectGoalFitFreeResult } from "@/domain/goal-fit/free-result"; import { readCompletedSession } from "@/storage/goal-fit-session";
const result=ref<ReturnType<typeof projectGoalFitFreeResult>|null>(null);const error=ref("");const reported=ref(false);
onLoad((query)=>{const id=typeof query?.sessionId==="string"?query.sessionId:"";const session=readCompletedSession(id);if(!session){error.value="未找到可用的测试结果，请重新开始测试。";return}result.value=projectGoalFitFreeResult(session.result);if(!reported.value){reported.value=true;void trackEvent("free_result_view",{metadata:{sessionId:id,overallScore:result.value.overallScore,resultVersion:session.result.resultVersion}})}});function home(){uni.reLaunch({url:"/pages/index/index"})}function retry(){uni.reLaunch({url:"/pages/test-entry/index"})}
</script>
<template><view class="page"><view v-if="result" class="card"><text class="score">{{result.overallScore}} 分</text><text class="title">{{result.overallConclusion.title}}</text><text class="summary">{{result.overallConclusion.summary}}</text><text class="section">首要风险</text><text class="risk">{{result.primaryRisk.title}}</text><text class="summary">{{result.primaryRisk.description}}</text><text class="section">风险点</text><view v-for="risk in result.riskPoints" :key="risk.title" class="risk-item"><text>{{risk.title}}</text><text>{{risk.description}}</text></view><text class="section">行动提醒</text><text class="summary">{{result.actionReminder}}</text><button class="primary" @click="home">返回首页</button></view><view v-else class="card"><text class="title">结果暂不可用</text><text class="summary">{{error}}</text><button class="primary" @click="retry">重新测试</button><button @click="home">返回首页</button></view></view></template>
<style scoped>.page{min-height:100vh;padding:48rpx 32rpx;box-sizing:border-box}.card{background:#fff;padding:36rpx;border-radius:24rpx}.score,.title,.summary,.section,.risk,.risk-item text{display:block}.score{font-size:64rpx;font-weight:700;color:#4057d6}.title{font-size:40rpx;font-weight:700;margin:20rpx 0}.summary{line-height:1.65;color:#5f6675}.section{margin-top:36rpx;font-size:30rpx;font-weight:700}.risk{margin:16rpx 0;font-size:32rpx;font-weight:600}.risk-item{padding:20rpx 0;border-bottom:1rpx solid #eef0f5;line-height:1.55}.primary{margin-top:40rpx;background:#4057d6;color:#fff}</style>
